payload.cmd:
for d in /Users/jins/IO/sofar /Users/jins/IO/sofar-r1-fixes; do f=$d/.sofar/initiatives/r1-fixes/events.jsonl; [ -f $f ] && python3 -c "
import json
for l in open('$f'):
  e=json.loads(l)
  if e['type'] in ('session_ended','note_added','decision_logged'):
    t=json.dumps(e['payload'])
    if 'audit' in t.lower() or 'rust' in t.lower(): print('$d', e['type'], t[:3000]); print('---')
"; done 2>/dev/null | head -80
